describe('Promo Code Application and Discounted Total Display', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should apply promo code and display discounted total on successful validation', () => {
    // Intercept the API call to get the original total
    cy.intercept('GET', '/api/cart/total').as('getTotal');
    cy.wait('@getTotal');
    cy.get('[data-testid="original-total"]').should('be.visible').should('contain', '$100.00');

    // Enter a valid promo code
    cy.get('[data-testid="promo-code-input"]').type('SAVE10');
    cy.get('[data-testid="apply-promo-button"]').click();

    // Intercept the API call to apply the promo code
    cy.intercept('POST', '/api/cart/apply-promo').as('applyPromo');
    cy.wait('@applyPromo');

    // Verify the discounted total is displayed
    cy.get('[data-testid="discounted-total"]').should('be.visible').should('contain', '$90.00');

    // Verify the discount amount is shown
    cy.get('[data-testid="discount-amount"]').should('be.visible').should('contain', '$10.00');

    // Verify the promo code was applied successfully
    cy.get('[data-testid="promo-code-status"]').should('contain', 'Applied');

    // Verify the original total is still visible for reference
    cy.get('[data-testid="original-total"]').should('be.visible');
  });

  it('should show error when invalid promo code is entered', () => {
    // Intercept the API call to get the original total
    cy.intercept('GET', '/api/cart/total').as('getTotal');
    cy.wait('@getTotal');
    cy.get('[data-testid="original-total"]').should('be.visible').should('contain', '$100.00');

    // Enter an invalid promo code
    cy.get('[data-testid="promo-code-input"]').type('INVALIDCODE');
    cy.get('[data-testid="apply-promo-button"]').click();

    // Intercept the API call to apply the promo code
    cy.intercept('POST', '/api/cart/apply-promo').as('applyPromo');
    cy.wait('@applyPromo');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid promo code');

    // Verify the original total is still visible
    cy.get('[data-testid="original-total"]').should('be.visible');

    // Verify the discounted total is not displayed
    cy.get('[data-testid="discounted-total"]').should('not.exist');
  });
});
